import assert from 'node:assert/strict';
import test from 'node:test';
import {loadPortable} from './portable.mjs';

// Text generated by code is traced back to the string literals it comes from.
const portable = loadPortable();
const file = 'src/Composition.tsx';
/** Stamp of the first `<tag` opening element in `source`. */
const stampOf = (source, tag) => {
  const index = source.indexOf(`<${tag}`);
  const before = source.slice(0, index).split('\n');
  return `${file}:${before.length}:${before.at(-1).length + 1}`;
};
const inspect = (source, tag, rendered = '') => JSON.parse(portable.text(source, stampOf(source, tag), rendered));
const apply = (source, request) => JSON.parse(portable.edit(source, JSON.stringify(request)));
const setField = (source, tag, field, value) =>
  apply(source, {op: 'setLiteral', src: stampOf(source, tag), key: 'literal', offset: field.offset, text: field.raw, value});

/** Edits the only (or `pick`ed) field, checks the new text reads back, and undo restores the bytes. */
function roundTrip(source, tag, value, {rendered = '', pick = 0} = {}) {
  const summary = inspect(source, tag, rendered);
  assert.equal(summary.editable, false);
  assert.ok(summary.fields.length > pick, `no fields for ${tag}: ${JSON.stringify(summary)}`);
  const field = summary.fields[pick];
  const changed = setField(source, tag, field, value);
  // Escaping may move the literal by a byte (an attribute becoming an expression); match by value.
  assert.ok(inspect(changed.source, tag, '').fields.some(f => f.value === value), changed.source);
  assert.equal(apply(changed.source, changed.inverse).source, source);
  return {field, changed};
}

test('a const variable is edited at its declaration', () => {
  const source = `const title = 'Hello world';\nexport const Film = () => <h1 style={{fontSize: 80}}>{title}</h1>;\n`;
  const {field, changed} = roundTrip(source, 'h1', "It's \"new\"\nline");
  assert.equal(field.label, 'title');
  assert.equal(field.shared, true);
  assert.equal(field.line, 1);
  assert.match(changed.source, /^const title = 'It\\'s "new"\\nline';/);
});

test('mapped data arrays offer the row the frame shows', () => {
  const source = `const items = [{label: 'Alpha', n: 1}, {label: 'Beta', n: 2}, {label: \`Gamma\`, n: 3}];
export const Film = () => <ul>{items.map(item => <li key={item.n}>{item.label}</li>)}</ul>;
`;
  const all = inspect(source, 'li');
  assert.deepEqual(all.fields.map(f => f.value), ['Alpha', 'Beta', 'Gamma']);
  assert.deepEqual(inspect(source, 'li', 'Beta').fields.map(f => f.value), ['Beta']);
  roundTrip(source, 'li', 'Bravo', {rendered: 'Beta'});
  const {changed} = roundTrip(source, 'li', 'Ga`m${ma}', {rendered: 'Gamma'});
  assert.match(changed.source, /label: `Ga\\`m\\\$\{ma\}`/);
});

test('destructured component props are edited at the usage', () => {
  const source = `const Card = ({heading, body = 'Default body'}: {heading: string; body?: string}) => (
  <div><h2>{heading}</h2><p>{body}</p></div>
);
export const Film = () => <>
  <Card heading="First" />
  <Card heading={'Second'} body="Custom" />
</>;
`;
  assert.deepEqual(inspect(source, 'h2').fields.map(f => f.value), ['First', 'Second']);
  assert.deepEqual(inspect(source, 'p').fields.map(f => f.value), ['Default body', 'Custom']);
  const {changed} = roundTrip(source, 'h2', 'Has "quotes" & {braces}', {rendered: 'First'});
  assert.match(changed.source, /<Card heading=\{"Has \\"quotes\\" & \{braces\}"\} \/>/);
  roundTrip(source, 'h2', 'Plain', {rendered: 'First'});
});

test('props objects, string methods, templates and letter splits trace to their source', () => {
  const cases = [
    [`const Title = (props: {text: string}) => <h1>{props.text.toUpperCase()}</h1>;
export const Film = () => <Title text="make it move" />;`, 'h1', 'MAKE IT MOVE', 'make it move', true],
    [`const name = 'Ada';\nexport const Film = () => <h1>{\`\${name} wins\`}</h1>;`, 'h1', 'Ada wins', 'Ada', true],
    [`const word = "Kinetic";\nexport const Film = () => <div>{word.split('').map((c, i) => <span key={i}>{c}</span>)}</div>;`,
      'div', 'Kinetic', 'Kinetic', true],
    [`const DATA = {hero: {title: 'Deep' as const}};\nexport const Film = () => <h1>{DATA.hero.title}</h1>;`, 'h1', 'Deep', 'Deep', false],
    [`export const Film = ({frame}: {frame: number}) => <h1>{frame > 10 ? 'After' : "Before"}</h1>;`, 'h1', 'Before', 'Before', false],
  ];
  for (const [source, tag, rendered, value, transformed] of cases) {
    const summary = inspect(source, tag, rendered);
    assert.equal(summary.fields.length, 1, source);
    assert.equal(summary.fields[0].value, value, source);
    assert.equal(summary.fields[0].transformed, transformed, source);
    roundTrip(source, tag, 'Changed', {rendered});
  }
});

test('mixed literal text and expressions expose each literal part', () => {
  const source = `const score = 'Gold';\nexport const Film = () => <p>Score: {score}</p>;`;
  const summary = inspect(source, 'p', 'Score: Gold');
  assert.deepEqual(summary.fields.map(f => [f.label, f.value]), [['Text', 'Score: '], ['score', 'Gold']]);
  const {changed} = roundTrip(source, 'p', 'Rank: ');
  assert.match(changed.source, /<p>Rank: \{score\}<\/p>/);
  roundTrip(source, 'p', 'Silver', {pick: 1});
});

test('lettering helpers and film layers with bound text are traced', () => {
  const source = `const line = 'Make it move.';\nexport const Film = <Img src={lettering(line, 88)} />;`;
  roundTrip(source, 'Img', 'Move it.');
});

test('untraceable text offers fixed-text replacement that undo reverts', () => {
  const source = `export const Film = ({count}: {count: number}) => <h1 style={{opacity: 1}}>{Math.round(count)} views</h1>;`;
  const summary = inspect(source, 'h1');
  assert.deepEqual(summary.fields.map(f => f.value), [' views']);
  const bare = `export const Film = ({count}: {count: number}) => <h1>{Math.round(count)}</h1>;`;
  const none = inspect(bare, 'h1');
  assert.equal(none.fields.length, 0);
  assert.match(none.reason, /generated by code/);
  assert.equal(none.canReplace, true);
  const replaced = apply(bare, {op: 'replaceText', src: stampOf(bare, 'h1'), key: 'children', value: '1,024 "views"'});
  assert.equal(inspect(replaced.source, 'h1').value, '1,024 "views"');
  assert.equal(apply(replaced.source, replaced.inverse).source, bare);
  const lettered = `export const Film = <Img src={lettering(makeTitle(), 88)} />;`;
  const letter = apply(lettered, {op: 'replaceText', src: stampOf(lettered, 'Img'), key: 'children', value: 'Fixed'});
  assert.match(letter.source, /lettering\('Fixed', 88\)/);
  assert.equal(apply(letter.source, letter.inverse).source, lettered);
});

test('literal edits refuse stale offsets', () => {
  const source = `const title = 'Hello';\nexport const Film = () => <h1>{title}</h1>;`;
  const field = inspect(source, 'h1').fields[0];
  assert.throws(() => setField(`// moved\n${source}`, 'h1', field, 'x'), /stale-source:/);
});

test('parameters shadowing a module constant do not resolve to it', () => {
  const source = `const title = 'Module';\nconst Inner = ({title}: {title: string}) => <h1>{title}</h1>;\nexport const Film = () => <Inner title="Prop" />;`;
  assert.deepEqual(inspect(source, 'h1').fields.map(f => f.value), ['Prop']);
});

test('text passed as children between a component\'s tags is edited at the usage', () => {
  const source = `const Title = ({from, children}: {from: number; children: React.ReactNode}) => (
  <div style={{position: 'absolute', fontSize: 92}}>
    {children}
  </div>
);
export const Film = () => <>
  <Title from={1}>Until you hit render.</Title>
  <Title from={2}>
    Second title
  </Title>
</>;
`;
  const summary = inspect(source, 'div', 'Until you hit render.');
  assert.deepEqual(summary.fields.map(f => [f.label, f.value, f.shared]), [['children', 'Until you hit render.', true]]);
  const {changed} = roundTrip(source, 'div', 'Ready in real time.', {rendered: 'Until you hit render.'});
  assert.match(changed.source, /<Title from=\{1\}>Ready in real time\.<\/Title>/);
  const second = roundTrip(source, 'div', 'New <second>', {rendered: 'Second title'});
  assert.match(second.changed.source, /<Title from=\{2\}>\{"New <second>"\}<\/Title>/);
});
